import json
from pathlib import Path


class Preferences:
    def __init__(self, store_path: Path):
        self.store_path = store_path
        self.theme = "light"
        self.language = "en"

    def save(self) -> None:
        with open(self.store_path, "w") as handle:
            json.dump({"theme": self.theme, "language": self.language}, handle)


def apply_preferences(prefs: Preferences, updates: dict[str, str]) -> None:
    """Apply the fields a user submitted from the settings form, then persist them."""
    for key, value in updates.items():
        setattr(prefs, key, value)
    prefs.save()
